INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT qq.id, 'Update a small canary group first, monitor for automation regressions over a defined window, then roll out in batches while keeping a changelog', 'تحديث مجموعة تجريبية صغيرة أولًا، مراقبة أي تراجع في الأتمتة خلال فترة محددة، ثم الطرح على دفعات مع الاحتفاظ بسجل تغييرات', TRUE, 1 FROM public.quiz_questions qq JOIN public.quizzes q ON q.id = qq.quiz_id JOIN public.modules m ON m.id = q.module_id WHERE m.slug = 'sonoff-mesh-security-hardening' AND q.tier = 'gold' AND qq.question = 'You''re hardening a 40-device commercial deployment where different vendors'' firmware update cycles are unpredictable. What staged rollout strategy minimizes risk of a building-wide automation outage?';
